function main() {
  const esData = JSON.parse(fs.readFileSync(ES_DATA_PATH, 'utf8'));
  if (!esData["$mechanic"]) esData["$mechanic"] = {};
  if (!esData["$mechanic"].texts) esData["$mechanic"].texts = {};
  if (!esData["$mechanic"].labels) esData["$mechanic"].labels = {};

  // Merge labels
  for (const [k, v] of Object.entries(LABELS_ES)) {
    esData["$mechanic"].labels[k] = v;
  }

  // Merge texts
  let updatedTexts = 0;
  for (const [k, v] of Object.entries(TEXTS_ES)) {
    esData["$mechanic"].texts[k] = v;
    updatedTexts++;
  }

  fs.writeFileSync(ES_DATA_PATH, JSON.stringify(esData, null, 2), 'utf8');
  console.log(`Updated es/data.json: ${Object.keys(LABELS_ES).length} labels, ${updatedTexts} texts.`);
}

main();
